-- Additive local upgrade generated from the current EF model for personalized-tour support.
-- Existing business rows are retained. No fake migration history or demo records are inserted.
-- Includes the missing visit/navigation/reward/access prerequisites used by the existing services.
-- Apply AddUserActiveState.sql and AddCatalogReadSchema.sql first on older local databases.
BEGIN;
SET LOCAL search_path = public;
SET LOCAL lock_timeout = '5s';


CREATE TABLE IF NOT EXISTS point_transactions (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "UserId" uuid NOT NULL,
    "Points" integer NOT NULL,
    "Reason" character varying(50) NOT NULL,
    "RefType" character varying(50) NOT NULL,
    "RefId" bigint NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_point_transactions" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_point_transactions_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE RESTRICT
);

CREATE TABLE IF NOT EXISTS badges (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "MuseumId" integer,
    "Code" character varying(50) NOT NULL,
    "Name" character varying(200) NOT NULL,
    "RuleJson" jsonb NOT NULL,
    CONSTRAINT "PK_badges" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_badges_museums_MuseumId" FOREIGN KEY ("MuseumId") REFERENCES museums ("Id") ON DELETE RESTRICT
);

CREATE TABLE IF NOT EXISTS buildings (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "MuseumId" integer NOT NULL,
    "Name" character varying(200) NOT NULL,
    CONSTRAINT "PK_buildings" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_buildings_museums_MuseumId" FOREIGN KEY ("MuseumId") REFERENCES museums ("Id") ON DELETE RESTRICT
);

CREATE TABLE IF NOT EXISTS commerce_products (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "MuseumId" integer NOT NULL,
    "Name" character varying(200) NOT NULL,
    "Kind" character varying(20) NOT NULL,
    "Price" numeric(18,2) NOT NULL,
    "Currency" character varying(3) NOT NULL,
    "Seats" integer NOT NULL,
    "ValidityHours" integer,
    "ValidityStartsAt" text,
    "ResourceIdsJson" text NOT NULL,
    "IsActive" boolean NOT NULL,
    CONSTRAINT "PK_commerce_products" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_commerce_products_museums_MuseumId" FOREIGN KEY ("MuseumId") REFERENCES museums ("Id") ON DELETE RESTRICT
);

CREATE TABLE IF NOT EXISTS personalized_tours (
    "Id" uuid NOT NULL,
    "OwnerId" uuid NOT NULL,
    "MuseumId" integer NOT NULL,
    "SnapshotJson" jsonb NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_personalized_tours" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_personalized_tours_Users_OwnerId" FOREIGN KEY ("OwnerId") REFERENCES "Users" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_personalized_tours_museums_MuseumId" FOREIGN KEY ("MuseumId") REFERENCES museums ("Id") ON DELETE RESTRICT
);

CREATE TABLE IF NOT EXISTS tours (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "MuseumId" integer NOT NULL,
    "CreatedBy" uuid NOT NULL,
    "Title" character varying(200) NOT NULL,
    "Description" character varying(4000) NOT NULL,
    "EstimatedMinutes" integer NOT NULL,
    "Status" character varying(20) NOT NULL,
    "Revision" integer NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_tours" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_tours_Users_CreatedBy" FOREIGN KEY ("CreatedBy") REFERENCES "Users" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_tours_museums_MuseumId" FOREIGN KEY ("MuseumId") REFERENCES museums ("Id") ON DELETE RESTRICT
);

CREATE TABLE IF NOT EXISTS user_badges (
    "UserId" uuid NOT NULL,
    "BadgeId" integer NOT NULL,
    "AwardedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_user_badges" PRIMARY KEY ("UserId", "BadgeId"),
    CONSTRAINT "FK_user_badges_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_user_badges_badges_BadgeId" FOREIGN KEY ("BadgeId") REFERENCES badges ("Id") ON DELETE RESTRICT
);

CREATE TABLE IF NOT EXISTS purchase_orders (
    "Id" uuid NOT NULL,
    "BuyerId" uuid NOT NULL,
    "MuseumId" integer NOT NULL,
    "ProductId" integer NOT NULL,
    "ProductName" text NOT NULL,
    "ProductKind" text NOT NULL,
    "Amount" numeric(18,2) NOT NULL,
    "Currency" character varying(3) NOT NULL,
    "Seats" integer NOT NULL,
    "ValidityHours" integer NOT NULL,
    "ValidityStartsAt" text NOT NULL,
    "ResourceIdsJson" text NOT NULL,
    "BuyerName" text NOT NULL,
    "BuyerDetailsJson" text NOT NULL,
    "Status" text NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "PaidAt" timestamp with time zone,
    "ExpiresAt" timestamp with time zone,
    "GroupKeyHash" character varying(64),
    CONSTRAINT "PK_purchase_orders" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_purchase_orders_Users_BuyerId" FOREIGN KEY ("BuyerId") REFERENCES "Users" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_purchase_orders_commerce_products_ProductId" FOREIGN KEY ("ProductId") REFERENCES commerce_products ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_purchase_orders_museums_MuseumId" FOREIGN KEY ("MuseumId") REFERENCES museums ("Id") ON DELETE RESTRICT
);

CREATE TABLE IF NOT EXISTS indoor_maps (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "MuseumId" integer NOT NULL,
    "FloorId" integer,
    "Name" character varying(200) NOT NULL,
    "Revision" integer NOT NULL,
    "ImageKey" text,
    "ImageWidth" integer NOT NULL,
    "ImageHeight" integer NOT NULL,
    "PublishedJson" jsonb,
    "PublishedAt" timestamp with time zone,
    CONSTRAINT "PK_indoor_maps" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_indoor_maps_floors_FloorId" FOREIGN KEY ("FloorId") REFERENCES floors ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_indoor_maps_museums_MuseumId" FOREIGN KEY ("MuseumId") REFERENCES museums ("Id") ON DELETE RESTRICT
);

CREATE TABLE IF NOT EXISTS museum_passes (
    "Id" uuid NOT NULL,
    "OrderId" uuid NOT NULL,
    "UserId" uuid NOT NULL,
    "ClaimedAt" timestamp with time zone NOT NULL,
    "RevokedAt" timestamp with time zone,
    CONSTRAINT "PK_museum_passes" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_museum_passes_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_museum_passes_purchase_orders_OrderId" FOREIGN KEY ("OrderId") REFERENCES purchase_orders ("Id") ON DELETE RESTRICT
);

CREATE TABLE IF NOT EXISTS payment_attempts (
    "Id" uuid NOT NULL,
    "OrderId" uuid NOT NULL,
    "Status" text NOT NULL,
    "Reference" text,
    "FailureReason" text,
    "ConfirmedBy" uuid,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CompletedAt" timestamp with time zone,
    CONSTRAINT "PK_payment_attempts" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_payment_attempts_Users_ConfirmedBy" FOREIGN KEY ("ConfirmedBy") REFERENCES "Users" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_payment_attempts_purchase_orders_OrderId" FOREIGN KEY ("OrderId") REFERENCES purchase_orders ("Id") ON DELETE RESTRICT
);

CREATE TABLE IF NOT EXISTS purchase_invoices (
    "Id" uuid NOT NULL,
    "OrderId" uuid NOT NULL,
    "Number" text NOT NULL,
    "BuyerName" text NOT NULL,
    "BuyerDetailsJson" text NOT NULL,
    "ProductName" text NOT NULL,
    "ProductKind" text NOT NULL,
    "Seats" integer NOT NULL,
    "Amount" numeric(18,2) NOT NULL,
    "Currency" text NOT NULL,
    "IssuedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_purchase_invoices" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_purchase_invoices_purchase_orders_OrderId" FOREIGN KEY ("OrderId") REFERENCES purchase_orders ("Id") ON DELETE RESTRICT
);

CREATE TABLE IF NOT EXISTS map_nodes (
    "Id" uuid NOT NULL,
    "IndoorMapId" integer NOT NULL,
    "Label" character varying(200) NOT NULL,
    "Type" character varying(30) NOT NULL,
    "X" double precision NOT NULL,
    "Y" double precision NOT NULL,
    CONSTRAINT "PK_map_nodes" PRIMARY KEY ("Id"),
    CONSTRAINT "AK_map_nodes_IndoorMapId_Id" UNIQUE ("IndoorMapId", "Id"),
    CONSTRAINT "CK_map_nodes_xy" CHECK ("X" BETWEEN 0 AND 1 AND "Y" BETWEEN 0 AND 1),
    CONSTRAINT "FK_map_nodes_indoor_maps_IndoorMapId" FOREIGN KEY ("IndoorMapId") REFERENCES indoor_maps ("Id") ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS commerce_resources (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "MuseumId" integer NOT NULL,
    "Name" character varying(200) NOT NULL,
    "Kind" character varying(20) NOT NULL,
    "AccessLevel" character varying(20) NOT NULL,
    "ArtifactId" integer,
    "ScopeReference" character varying(200),
    CONSTRAINT "PK_commerce_resources" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_commerce_resources_artifacts_ArtifactId" FOREIGN KEY ("ArtifactId") REFERENCES artifacts ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_commerce_resources_museums_MuseumId" FOREIGN KEY ("MuseumId") REFERENCES museums ("Id") ON DELETE RESTRICT
);

CREATE TABLE IF NOT EXISTS questions (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "ArtifactId" integer NOT NULL,
    "LanguageCode" character varying(35) NOT NULL,
    "Content" character varying(4000) NOT NULL,
    "Explanation" character varying(4000) NOT NULL,
    "Status" character varying(20) NOT NULL,
    "CreatedBy" uuid NOT NULL,
    "ReviewedBy" uuid,
    "ReviewedAt" timestamp with time zone,
    "ReviewNote" character varying(1000),
    "CreatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_questions" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_questions_Users_CreatedBy" FOREIGN KEY ("CreatedBy") REFERENCES "Users" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_questions_Users_ReviewedBy" FOREIGN KEY ("ReviewedBy") REFERENCES "Users" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_questions_artifacts_ArtifactId" FOREIGN KEY ("ArtifactId") REFERENCES artifacts ("Id") ON DELETE RESTRICT
);

CREATE TABLE IF NOT EXISTS quizzes (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "ArtifactId" integer NOT NULL,
    "Title" character varying(200) NOT NULL,
    "Status" character varying(20) NOT NULL,
    "CreatedBy" uuid NOT NULL,
    "QuestionsPerAttempt" integer NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_quizzes" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_quizzes_Users_CreatedBy" FOREIGN KEY ("CreatedBy") REFERENCES "Users" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_quizzes_artifacts_ArtifactId" FOREIGN KEY ("ArtifactId") REFERENCES artifacts ("Id") ON DELETE RESTRICT
);

CREATE TABLE IF NOT EXISTS recognition_history (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "UserId" uuid NOT NULL,
    "VisitId" integer,
    "ArtifactId" integer,
    "Method" character varying(20) NOT NULL,
    "IsSuccess" boolean NOT NULL,
    "RecognizedAt" timestamp with time zone NOT NULL,
    "RequestId" uuid NOT NULL,
    CONSTRAINT "PK_recognition_history" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_recognition_history_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_recognition_history_artifacts_ArtifactId" FOREIGN KEY ("ArtifactId") REFERENCES artifacts ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_recognition_history_visits_VisitId" FOREIGN KEY ("VisitId") REFERENCES visits ("Id") ON DELETE RESTRICT
);

CREATE TABLE IF NOT EXISTS staff_assignments (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "UserId" uuid NOT NULL,
    "MuseumId" integer NOT NULL,
    "GalleryId" integer,
    "ArtifactId" integer,
    "AssignedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_staff_assignments" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_staff_assignments_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_staff_assignments_artifacts_ArtifactId" FOREIGN KEY ("ArtifactId") REFERENCES artifacts ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_staff_assignments_galleries_GalleryId" FOREIGN KEY ("GalleryId") REFERENCES galleries ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_staff_assignments_museums_MuseumId" FOREIGN KEY ("MuseumId") REFERENCES museums ("Id") ON DELETE RESTRICT
);

CREATE TABLE IF NOT EXISTS tour_items (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "TourId" integer NOT NULL,
    "ArtifactId" integer NOT NULL,
    "OrderNo" integer NOT NULL,
    CONSTRAINT "PK_tour_items" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_tour_items_artifacts_ArtifactId" FOREIGN KEY ("ArtifactId") REFERENCES artifacts ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_tour_items_tours_TourId" FOREIGN KEY ("TourId") REFERENCES tours ("Id") ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS map_edges (
    "Id" uuid NOT NULL,
    "IndoorMapId" integer NOT NULL,
    "FromNodeId" uuid NOT NULL,
    "ToNodeId" uuid NOT NULL,
    "Bidirectional" boolean NOT NULL,
    "IsAccessible" boolean NOT NULL,
    CONSTRAINT "PK_map_edges" PRIMARY KEY ("Id"),
    CONSTRAINT "CK_map_edges_distinct" CHECK ("FromNodeId" <> "ToNodeId"),
    CONSTRAINT "FK_map_edges_indoor_maps_IndoorMapId" FOREIGN KEY ("IndoorMapId") REFERENCES indoor_maps ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_map_edges_map_nodes_IndoorMapId_FromNodeId" FOREIGN KEY ("IndoorMapId", "FromNodeId") REFERENCES map_nodes ("IndoorMapId", "Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_map_edges_map_nodes_IndoorMapId_ToNodeId" FOREIGN KEY ("IndoorMapId", "ToNodeId") REFERENCES map_nodes ("IndoorMapId", "Id") ON DELETE RESTRICT
);

CREATE TABLE IF NOT EXISTS map_markers (
    "Id" uuid NOT NULL,
    "IndoorMapId" integer NOT NULL,
    "Label" character varying(200) NOT NULL,
    "Type" character varying(30) NOT NULL,
    "X" double precision NOT NULL,
    "Y" double precision NOT NULL,
    "ArtifactId" integer,
    "GalleryId" integer,
    "NodeId" uuid,
    "IsDestination" boolean NOT NULL,
    "IsActive" boolean NOT NULL,
    CONSTRAINT "PK_map_markers" PRIMARY KEY ("Id"),
    CONSTRAINT "CK_map_markers_xy" CHECK ("X" BETWEEN 0 AND 1 AND "Y" BETWEEN 0 AND 1),
    CONSTRAINT "FK_map_markers_artifacts_ArtifactId" FOREIGN KEY ("ArtifactId") REFERENCES artifacts ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_map_markers_galleries_GalleryId" FOREIGN KEY ("GalleryId") REFERENCES galleries ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_map_markers_indoor_maps_IndoorMapId" FOREIGN KEY ("IndoorMapId") REFERENCES indoor_maps ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_map_markers_map_nodes_IndoorMapId_NodeId" FOREIGN KEY ("IndoorMapId", "NodeId") REFERENCES map_nodes ("IndoorMapId", "Id") ON DELETE RESTRICT
);

CREATE TABLE IF NOT EXISTS question_options (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "QuestionId" integer NOT NULL,
    "Content" character varying(1000) NOT NULL,
    "IsCorrect" boolean NOT NULL,
    "OrderNo" integer NOT NULL,
    CONSTRAINT "PK_question_options" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_question_options_questions_QuestionId" FOREIGN KEY ("QuestionId") REFERENCES questions ("Id") ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS quiz_questions (
    "QuizId" integer NOT NULL,
    "QuestionId" integer NOT NULL,
    CONSTRAINT "PK_quiz_questions" PRIMARY KEY ("QuizId", "QuestionId"),
    CONSTRAINT "FK_quiz_questions_questions_QuestionId" FOREIGN KEY ("QuestionId") REFERENCES questions ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_quiz_questions_quizzes_QuizId" FOREIGN KEY ("QuizId") REFERENCES quizzes ("Id") ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS daily_quiz_entries (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "UserId" uuid NOT NULL,
    "QuizId" integer NOT NULL,
    "ArtifactId" integer NOT NULL,
    "RecognitionId" bigint NOT NULL,
    "VisitId" integer,
    "EntryDate" date NOT NULL,
    "Status" character varying(20) NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_daily_quiz_entries" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_daily_quiz_entries_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_daily_quiz_entries_artifacts_ArtifactId" FOREIGN KEY ("ArtifactId") REFERENCES artifacts ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_daily_quiz_entries_quizzes_QuizId" FOREIGN KEY ("QuizId") REFERENCES quizzes ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_daily_quiz_entries_recognition_history_RecognitionId" FOREIGN KEY ("RecognitionId") REFERENCES recognition_history ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_daily_quiz_entries_visits_VisitId" FOREIGN KEY ("VisitId") REFERENCES visits ("Id") ON DELETE RESTRICT
);

CREATE TABLE IF NOT EXISTS visit_items (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "VisitId" integer NOT NULL,
    "ArtifactId" integer NOT NULL,
    "TourItemId" integer,
    "LastVisitedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_visit_items" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_visit_items_artifacts_ArtifactId" FOREIGN KEY ("ArtifactId") REFERENCES artifacts ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_visit_items_tour_items_TourItemId" FOREIGN KEY ("TourItemId") REFERENCES tour_items ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_visit_items_visits_VisitId" FOREIGN KEY ("VisitId") REFERENCES visits ("Id") ON DELETE RESTRICT
);

CREATE TABLE IF NOT EXISTS quiz_attempts (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "UserId" uuid NOT NULL,
    "QuizId" integer NOT NULL,
    "DailyEntryId" bigint NOT NULL,
    "Mode" character varying(20) NOT NULL,
    "Status" character varying(20) NOT NULL,
    "TotalQuestions" integer NOT NULL,
    "CorrectCount" integer NOT NULL,
    "Score" integer NOT NULL,
    "StartedAt" timestamp with time zone NOT NULL,
    "CompletedAt" timestamp with time zone,
    CONSTRAINT "PK_quiz_attempts" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_quiz_attempts_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_quiz_attempts_daily_quiz_entries_DailyEntryId" FOREIGN KEY ("DailyEntryId") REFERENCES daily_quiz_entries ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_quiz_attempts_quizzes_QuizId" FOREIGN KEY ("QuizId") REFERENCES quizzes ("Id") ON DELETE RESTRICT
);

CREATE TABLE IF NOT EXISTS quiz_attempt_answers (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "AttemptId" bigint NOT NULL,
    "QuestionId" integer NOT NULL,
    "SelectedOptionId" integer,
    "IsCorrect" boolean NOT NULL,
    "Points" integer NOT NULL,
    "AnsweredAt" timestamp with time zone,
    "OrderNo" integer NOT NULL,
    CONSTRAINT "PK_quiz_attempt_answers" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_quiz_attempt_answers_question_options_SelectedOptionId" FOREIGN KEY ("SelectedOptionId") REFERENCES question_options ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_quiz_attempt_answers_questions_QuestionId" FOREIGN KEY ("QuestionId") REFERENCES questions ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_quiz_attempt_answers_quiz_attempts_AttemptId" FOREIGN KEY ("AttemptId") REFERENCES quiz_attempts ("Id") ON DELETE RESTRICT
);

CREATE UNIQUE INDEX IF NOT EXISTS "IX_badges_Code" ON badges ("Code");

CREATE INDEX IF NOT EXISTS "IX_badges_MuseumId" ON badges ("MuseumId");

CREATE INDEX IF NOT EXISTS "IX_buildings_MuseumId" ON buildings ("MuseumId");

CREATE INDEX IF NOT EXISTS "IX_commerce_products_MuseumId" ON commerce_products ("MuseumId");

CREATE UNIQUE INDEX IF NOT EXISTS "IX_commerce_resources_ArtifactId" ON commerce_resources ("ArtifactId");

CREATE INDEX IF NOT EXISTS "IX_commerce_resources_MuseumId" ON commerce_resources ("MuseumId");

CREATE INDEX IF NOT EXISTS "IX_daily_quiz_entries_ArtifactId" ON daily_quiz_entries ("ArtifactId");

CREATE INDEX IF NOT EXISTS "IX_daily_quiz_entries_QuizId" ON daily_quiz_entries ("QuizId");

CREATE INDEX IF NOT EXISTS "IX_daily_quiz_entries_RecognitionId" ON daily_quiz_entries ("RecognitionId");

CREATE UNIQUE INDEX IF NOT EXISTS "IX_daily_quiz_entries_UserId_QuizId_EntryDate" ON daily_quiz_entries ("UserId", "QuizId", "EntryDate");

CREATE INDEX IF NOT EXISTS "IX_daily_quiz_entries_VisitId" ON daily_quiz_entries ("VisitId");

CREATE UNIQUE INDEX IF NOT EXISTS "IX_indoor_maps_FloorId" ON indoor_maps ("FloorId") WHERE "FloorId" IS NOT NULL;

CREATE UNIQUE INDEX IF NOT EXISTS "IX_indoor_maps_MuseumId" ON indoor_maps ("MuseumId") WHERE "FloorId" IS NULL;

CREATE UNIQUE INDEX IF NOT EXISTS "IX_map_edges_IndoorMapId_FromNodeId_ToNodeId" ON map_edges ("IndoorMapId", "FromNodeId", "ToNodeId");

CREATE INDEX IF NOT EXISTS "IX_map_edges_IndoorMapId_ToNodeId" ON map_edges ("IndoorMapId", "ToNodeId");

CREATE INDEX IF NOT EXISTS "IX_map_markers_ArtifactId" ON map_markers ("ArtifactId");

CREATE INDEX IF NOT EXISTS "IX_map_markers_GalleryId" ON map_markers ("GalleryId");

CREATE INDEX IF NOT EXISTS "IX_map_markers_IndoorMapId_NodeId" ON map_markers ("IndoorMapId", "NodeId");

CREATE UNIQUE INDEX IF NOT EXISTS "IX_museum_passes_OrderId_UserId" ON museum_passes ("OrderId", "UserId");

CREATE INDEX IF NOT EXISTS "IX_museum_passes_UserId" ON museum_passes ("UserId");

CREATE INDEX IF NOT EXISTS "IX_payment_attempts_ConfirmedBy" ON payment_attempts ("ConfirmedBy");

CREATE UNIQUE INDEX IF NOT EXISTS "IX_payment_attempts_pending" ON payment_attempts ("OrderId") WHERE "Status" = 'pending';

CREATE UNIQUE INDEX IF NOT EXISTS "IX_payment_attempts_Reference" ON payment_attempts ("Reference") WHERE "Reference" IS NOT NULL;

CREATE UNIQUE INDEX IF NOT EXISTS "IX_payment_attempts_success" ON payment_attempts ("OrderId") WHERE "Status" = 'succeeded';

CREATE INDEX IF NOT EXISTS "IX_personalized_tours_MuseumId" ON personalized_tours ("MuseumId");

CREATE INDEX IF NOT EXISTS "IX_personalized_tours_OwnerId_CreatedAt" ON personalized_tours ("OwnerId", "CreatedAt");

CREATE UNIQUE INDEX IF NOT EXISTS "IX_point_transactions_UserId_Reason_RefType_RefId" ON point_transactions ("UserId", "Reason", "RefType", "RefId");

CREATE UNIQUE INDEX IF NOT EXISTS "IX_purchase_invoices_Number" ON purchase_invoices ("Number");

CREATE UNIQUE INDEX IF NOT EXISTS "IX_purchase_invoices_OrderId" ON purchase_invoices ("OrderId");

CREATE INDEX IF NOT EXISTS "IX_purchase_orders_BuyerId_CreatedAt" ON purchase_orders ("BuyerId", "CreatedAt");

CREATE UNIQUE INDEX IF NOT EXISTS "IX_purchase_orders_GroupKeyHash" ON purchase_orders ("GroupKeyHash");

CREATE INDEX IF NOT EXISTS "IX_purchase_orders_MuseumId_PaidAt" ON purchase_orders ("MuseumId", "PaidAt");

CREATE INDEX IF NOT EXISTS "IX_purchase_orders_ProductId" ON purchase_orders ("ProductId");

CREATE INDEX IF NOT EXISTS "IX_question_options_QuestionId" ON question_options ("QuestionId");

CREATE INDEX IF NOT EXISTS "IX_questions_ArtifactId" ON questions ("ArtifactId");

CREATE INDEX IF NOT EXISTS "IX_questions_CreatedBy" ON questions ("CreatedBy");

CREATE INDEX IF NOT EXISTS "IX_questions_ReviewedBy" ON questions ("ReviewedBy");

CREATE UNIQUE INDEX IF NOT EXISTS "IX_quiz_attempt_answers_AttemptId_QuestionId" ON quiz_attempt_answers ("AttemptId", "QuestionId");

CREATE INDEX IF NOT EXISTS "IX_quiz_attempt_answers_QuestionId" ON quiz_attempt_answers ("QuestionId");

CREATE INDEX IF NOT EXISTS "IX_quiz_attempt_answers_SelectedOptionId" ON quiz_attempt_answers ("SelectedOptionId");

CREATE UNIQUE INDEX IF NOT EXISTS "IX_quiz_attempts_DailyEntryId" ON quiz_attempts ("DailyEntryId") WHERE "Status" = 'in_progress';

CREATE INDEX IF NOT EXISTS "IX_quiz_attempts_QuizId" ON quiz_attempts ("QuizId");

CREATE INDEX IF NOT EXISTS "IX_quiz_attempts_UserId" ON quiz_attempts ("UserId");

CREATE INDEX IF NOT EXISTS "IX_quiz_questions_QuestionId" ON quiz_questions ("QuestionId");

CREATE INDEX IF NOT EXISTS "IX_quizzes_ArtifactId" ON quizzes ("ArtifactId");

CREATE INDEX IF NOT EXISTS "IX_quizzes_CreatedBy" ON quizzes ("CreatedBy");

CREATE INDEX IF NOT EXISTS "IX_recognition_history_ArtifactId" ON recognition_history ("ArtifactId");

CREATE INDEX IF NOT EXISTS "IX_recognition_history_UserId_RecognizedAt" ON recognition_history ("UserId", "RecognizedAt");

CREATE UNIQUE INDEX IF NOT EXISTS "IX_recognition_history_UserId_RequestId" ON recognition_history ("UserId", "RequestId");

CREATE INDEX IF NOT EXISTS "IX_recognition_history_VisitId" ON recognition_history ("VisitId");

CREATE INDEX IF NOT EXISTS "IX_staff_assignments_ArtifactId" ON staff_assignments ("ArtifactId");

CREATE INDEX IF NOT EXISTS "IX_staff_assignments_GalleryId" ON staff_assignments ("GalleryId");

