ALTER TABLE visits ADD COLUMN IF NOT EXISTS "PersonalizedTourId" uuid;
ALTER TABLE artifact_content_versions ADD COLUMN IF NOT EXISTS "NarrationText" text;
ALTER TABLE artifact_content_versions ADD COLUMN IF NOT EXISTS "AudioUrl" character varying(1000);
CREATE INDEX IF NOT EXISTS "IX_visits_PersonalizedTourId" ON visits ("PersonalizedTourId");
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM visits v WHERE v."TourId" IS NOT NULL AND NOT EXISTS (SELECT 1 FROM tours t WHERE t."Id" = v."TourId")) THEN
        RAISE EXCEPTION 'Legacy visits reference missing tours. Reconcile those references before applying this upgrade; no visit has been deleted.';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'visits'::regclass AND conname = 'FK_visits_personalized_tours_PersonalizedTourId') THEN
        ALTER TABLE visits ADD CONSTRAINT "FK_visits_personalized_tours_PersonalizedTourId" FOREIGN KEY ("PersonalizedTourId") REFERENCES personalized_tours("Id") ON DELETE RESTRICT;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'visits'::regclass AND conname = 'FK_visits_tours_TourId') THEN
        ALTER TABLE visits ADD CONSTRAINT "FK_visits_tours_TourId" FOREIGN KEY ("TourId") REFERENCES tours("Id") ON DELETE RESTRICT;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'visits'::regclass AND conname = 'CK_visits_one_itinerary') THEN
        ALTER TABLE visits ADD CONSTRAINT "CK_visits_one_itinerary" CHECK ("TourId" IS NULL OR "PersonalizedTourId" IS NULL);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'floors'::regclass AND conname = 'FK_floors_buildings_BuildingId') THEN
        ALTER TABLE floors ADD CONSTRAINT "FK_floors_buildings_BuildingId" FOREIGN KEY ("BuildingId") REFERENCES buildings("Id") ON DELETE RESTRICT;
    END IF;
END $$;
COMMIT;
